#include <bits/stdc++.h>
using namespace std;
using ll = long long;

template<int MAX_EDGES>
struct Dinic {
    static constexpr int INF = 1e9;
    int n, src, sink;
    vector<int> head, cur, dist;
    struct Edge { int to, rev, cap; };
    vector<vector<Edge>> g;

    Dinic(int nodes) : n(nodes), head(nodes, -1), cur(nodes), dist(nodes), g(nodes) {}

    void add_edge(int u, int v, int cap) {
        g[u].push_back({v, (int)g[v].size(), cap});
        g[v].push_back({u, (int)g[u].size()-1, 0});
    }

    bool bfs() {
        fill(dist.begin(), dist.end(), -1);
        queue<int> q;
        q.push(src);
        dist[src] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : g[u]) {
                if (dist[e.to] == -1 && e.cap > 0) {
                    dist[e.to] = dist[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return dist[sink] != -1;
    }

    int dfs(int u, int flow) {
        if (u == sink) return flow;
        for (int& i = cur[u]; i < (int)g[u].size(); ++i) {
            auto& e = g[u][i];
            if (dist[e.to] == dist[u] + 1 && e.cap > 0) {
                int pushed = dfs(e.to, min(flow, e.cap));
                if (pushed > 0) {
                    e.cap -= pushed;
                    g[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int max_flow(int s, int t) {
        src = s; sink = t;
        int total = 0;
        while (bfs()) {
            fill(cur.begin(), cur.end(), 0);
            while (int pushed = dfs(src, INF)) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    vector<string> field(n), capsule(n);
    int src_node = 2 * n * n, sink_node = src_node + 1;
    Dinic<210> flow(2 * n * n + 2);

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i) {
        cin >> field[i];
        for (int j = 0; j < n; ++j) {
            if (field[i][j] == 'Z') {
                zx = i; zy = j;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> capsule[i];
        for (int j = 0; j < n; ++j) {
            if (isdigit(capsule[i][j])) {
                flow.add_edge(i * n + j + n * n, sink_node, capsule[i][j] - '0');
            }
        }
    }

    vector<vector<int>> distZ(n, vector<int>(n, 1e9));
    queue<pair<int,int>> q;
    distZ[zx][zy] = 0;
    q.push({zx, zy});
    vector<int> dx = {-1, 1, 0, 0}, dy = {0, 0, -1, 1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (distZ[x][y] == t) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distZ[nx][ny] == 1e9) {
                distZ[nx][ny] = distZ[x][y] + 1;
                if (isdigit(capsule[nx][ny])) {
                    flow.add_edge(zx * n + zy, nx * n + ny + n * n, 1e9);
                }
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(field[i][j])) {
                flow.add_edge(src_node, i * n + j, field[i][j] - '0');
                vector<vector<int>> distS(n, vector<int>(n, 1e9));
                queue<pair<int,int>> q2;
                distS[i][j] = 0;
                q2.push({i, j});
                while (!q2.empty()) {
                    auto [x, y] = q2.front(); q2.pop();
                    if (distS[x][y] == t) continue;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distS[nx][ny] == 1e9) {
                            distS[nx][ny] = distS[x][y] + 1;
                            if (isdigit(capsule[nx][ny])) {
                                flow.add_edge(i * n + j, nx * n + ny + n * n, 1e9);
                            }
                            q2.push({nx, ny});
                        }
                    }
                }
            }
        }
    }

    cout << flow.max_flow(src_node, sink_node) << '\n';
    return 0;
}
